import{I as a,o as h,c as d,j as e,a as n,J as t,w as i,b6 as c}from"./chunks/framework.COUcLbTA.js";const g={style:{margin:"50px 0"}},f=JSON.parse('{"title":"What to Do When You Encounter Errors While Coding - A Practical Guide to Asking AI with Screenshots","description":"Learn how to efficiently ask AI to solve various error problems during development. Master the standard process of screenshotting, describing, and locating problems, making AI your debugging assistant.","frontmatter":{"title":"What to Do When You Encounter Errors While Coding - A Practical Guide to Asking AI with Screenshots","description":"Learn how to efficiently ask AI to solve various error problems during development. Master the standard process of screenshotting, describing, and locating problems, making AI your debugging assistant."},"headers":[],"relativePath":"en/stage-1/appendix-b-common-errors/index.md","filePath":"en/stage-1/appendix-b-common-errors/index.md"}'),u={name:"en/stage-1/appendix-b-common-errors/index.md"},y=Object.assign(u,{setup(k){const o="Approx. <strong>30 minutes</strong>";return(b,s)=>{const l=a("ChapterIntroduction"),r=a("StepBar"),p=a("ClientOnly");return h(),d("div",null,[s[1]||(s[1]=e("h1",{id:"what-to-do-when-you-encounter-errors-while-coding",tabindex:"-1"},[n("What to Do When You Encounter Errors While Coding "),e("a",{class:"header-anchor",href:"#what-to-do-when-you-encounter-errors-while-coding","aria-label":"Permalink to “What to Do When You Encounter Errors While Coding”"},"​")],-1)),s[2]||(s[2]=e("h2",{id:"chapter-overview",tabindex:"-1"},[n("Chapter Overview "),e("a",{class:"header-anchor",href:"#chapter-overview","aria-label":"Permalink to “Chapter Overview”"},"​")],-1)),t(l,{duration:o,tags:["Debugging Skills","AI Collaboration","Problem Solving","Developer Tools"],coreOutput:"A standardized error troubleshooting process",expectedOutput:"Ability to independently solve 90% of common errors"},{default:i(()=>[...s[0]||(s[0]=[e("p",null,"In the AI era, the way we troubleshoot errors has changed.",-1),e("p",null,"You don't need to memorize all error types, you don't need to become a debugging expert, and you don't even need to understand what the error means.",-1),e("p",null,[e("strong",null,"You only need to learn one thing: how to ask AI.")],-1),e("p",null,[n("This chapter will teach you a troubleshooting process "),e("strong",null,"from simple to advanced"),n(":")],-1),e("ol",null,[e("li",null,[e("strong",null,"Step 1: Ask directly"),n(": Describe the phenomenon + screenshot, ask in one sentence")]),e("li",null,[e("strong",null,"Step 2: Add information"),n(": If it can't be solved, open F12 to add key information")])],-1),e("p",null,[n("After mastering this process, "),e("strong",null,"you'll be able to solve 90% of errors yourself"),n(".")],-1)])]),_:1}),s[3]||(s[3]=e("div",{class:"info custom-block"},[e("p",{class:"custom-block-title"},"Note"),e("p",null,"All methods in this chapter are based on actual experience with AI IDEs like Cursor/Trae/Claude, and can be directly applied to daily development.")],-1)),e("div",g,[t(p,null,{default:i(()=>[t(r,{active:0,items:[{title:"Ask Directly",description:"Describe phenomenon + screenshot"},{title:"Add Information",description:"Open F12 to locate problem"},{title:"Iterate",description:"Until problem is solved"}]})]),_:1})]),s[4]||(s[4]=c(`<h2 id="_1-core-mindset-screenshot-and-ask-ai" tabindex="-1">1. Core Mindset: Screenshot and Ask AI <a class="header-anchor" href="#_1-core-mindset-screenshot-and-ask-ai" aria-label="Permalink to “1. Core Mindset: Screenshot and Ask AI”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Why is this chapter important?</p><p>Many beginners&#39; first reaction when encountering errors is:</p><ul><li>Panic and start randomly modifying code</li><li>Spend half an hour searching &quot;how to solve this specific error&quot;</li><li>Try to understand what the error means yourself</li><li>Debug alone until late at night</li></ul><p><strong>These are all wasting time.</strong></p><p>In the AI era, debugging has become a very simple matter:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>See error → Screenshot → Ask AI → Do what AI says</span></span></code></pre></div><p>You don&#39;t need to understand the error, you don&#39;t need to know how to debug, you don&#39;t even need to know where the problem is.</p><p><strong>You only need to learn how to ask.</strong></p></div><h3 id="_1-1-the-simplest-way-to-ask" tabindex="-1">1.1 The Simplest Way to Ask <a class="header-anchor" href="#_1-1-the-simplest-way-to-ask" aria-label="Permalink to “1.1 The Simplest Way to Ask”">​</a></h3><p>No complex templates needed, choose from two methods:</p><p><strong>Method 1: Describe the phenomenon</strong></p><p>Format: What you just did, what happened now</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I just modified the login page code, now the page is blank, what should I do?</span></span></code></pre></div><p><strong>Method 2: Screenshot</strong></p><p>Directly screenshot the current page or error message</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Screenshot]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>How to solve this error?</span></span></code></pre></div><p><strong>Best method: Description + Screenshot</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I just modified the login page code, now the page is blank.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Screenshot]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>What should I do?</span></span></code></pre></div><p><strong>Remember: Describe the context clearly, add a screenshot, and AI can help you solve the problem faster.</strong></p><h3 id="_1-2-how-to-explain-the-problem-clearly" tabindex="-1">1.2 How to Explain the Problem Clearly <a class="header-anchor" href="#_1-2-how-to-explain-the-problem-clearly" aria-label="Permalink to “1.2 How to Explain the Problem Clearly”">​</a></h3><p>Many beginners know they need to ask, but don&#39;t know how to say it. Actually, you only need to explain three things:</p><p><strong>1. What you just did</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I just clicked the save button</span></span>
<span class="line"><span>I just modified the login page code</span></span>
<span class="line"><span>I just refreshed the page</span></span></code></pre></div><p><strong>2. What you see now</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Now the page is blank</span></span>
<span class="line"><span>Now the button has no response when clicked</span></span>
<span class="line"><span>Now it shows an error message</span></span></code></pre></div><p><strong>3. What effect you want to achieve</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I want the data to save successfully</span></span>
<span class="line"><span>I want the page to display normally</span></span>
<span class="line"><span>I want a prompt to pop up after clicking the button</span></span></code></pre></div><p><strong>Complete example:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I just clicked the save button, now the page shows &quot;Save failed&quot; error.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Screenshot]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>I want the form data to save to the database successfully, what should I do?</span></span></code></pre></div><p><strong>Key principles:</strong></p><ul><li>Use plain language, no technical jargon needed</li><li>Speak in chronological order: what you did first, then what happened</li><li>State your expectations so AI knows what you want</li></ul><h2 id="_2-step-1-describe-the-phenomenon-directly-and-ask" tabindex="-1">2. Step 1: Describe the Phenomenon Directly and Ask <a class="header-anchor" href="#_2-step-1-describe-the-phenomenon-directly-and-ask" aria-label="Permalink to “2. Step 1: Describe the Phenomenon Directly and Ask”">​</a></h2><p>When encountering a problem, <strong>don&#39;t rush to open F12</strong>. First describe the phenomenon directly, screenshot the current page, and show it to AI.</p><p>Many times, AI can directly give a solution after seeing the screenshot.</p><h3 id="_2-1-how-to-describe-common-phenomena" tabindex="-1">2.1 How to Describe Common Phenomena <a class="header-anchor" href="#_2-1-how-to-describe-common-phenomena" aria-label="Permalink to “2.1 How to Describe Common Phenomena”">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Just describe directly</p><p><strong>Page is blank</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>The page opens blank, what should I do?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Screenshot]</span></span></code></pre></div><p><strong>Button click has no response</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Clicking this button has no response, help me check.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Screenshot]</span></span></code></pre></div><p><strong>Data won&#39;t save</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Clicked save, data didn&#39;t save, what should I do?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Screenshot]</span></span></code></pre></div><p><strong>Style displays incorrectly</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>This button position is off, how to adjust?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Screenshot]</span></span></code></pre></div><p><strong>API error</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Calling the API resulted in an error, help me check.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Screenshot]</span></span></code></pre></div></div><h3 id="_2-2-if-ai-solves-it-directly" tabindex="-1">2.2 If AI Solves It Directly <a class="header-anchor" href="#_2-2-if-ai-solves-it-directly" aria-label="Permalink to “2.2 If AI Solves It Directly”">​</a></h3><p>Congratulations, problem solved! Just modify according to what AI says.</p><h3 id="_2-3-if-ai-says-need-more-information" tabindex="-1">2.3 If AI Says &quot;Need More Information&quot; <a class="header-anchor" href="#_2-3-if-ai-says-need-more-information" aria-label="Permalink to “2.3 If AI Says &quot;Need More Information&quot;”">​</a></h3><p>Then you need to open F12 and add key information. Read on.</p><h2 id="_3-step-2-add-key-information" tabindex="-1">3. Step 2: Add Key Information <a class="header-anchor" href="#_3-step-2-add-key-information" aria-label="Permalink to “3. Step 2: Add Key Information”">​</a></h2><p>When AI says it needs more information, open F12 and screenshot the corresponding content based on the problem type.</p><h3 id="_3-1-when-to-add-information" tabindex="-1">3.1 When to Add Information <a class="header-anchor" href="#_3-1-when-to-add-information" aria-label="Permalink to “3.1 When to Add Information”">​</a></h3><p>AI might reply like this:</p><ul><li>&quot;Please open Console to see if there are any errors&quot;</li><li>&quot;Screenshot the Network panel for me to see&quot;</li><li>&quot;Need to see the specific error message&quot;</li></ul><p>At this point, add screenshots according to the guidance below.</p><h3 id="_3-2-add-console-information-page-blank-error" tabindex="-1">3.2 Add Console Information (Page Blank/Error) <a class="header-anchor" href="#_3-2-add-console-information-page-blank-error" aria-label="Permalink to “3.2 Add Console Information (Page Blank/Error)”">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Operation steps</p><p><strong>Step 1: Press F12 to open Developer Tools</strong></p><p>On Mac it&#39;s <code>Cmd+Option+I</code>, or right-click the page and select &quot;Inspect&quot;.</p><p><strong>Step 2: Switch to Console tab</strong></p><p><strong>Step 3: Screenshot the red error message</strong></p><p><strong>Step 4: Send to AI</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Console error is as follows:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Screenshot]</span></span></code></pre></div></div><h3 id="_3-3-add-network-information-data-issues-api-errors" tabindex="-1">3.3 Add Network Information (Data Issues/API Errors) <a class="header-anchor" href="#_3-3-add-network-information-data-issues-api-errors" aria-label="Permalink to “3.3 Add Network Information (Data Issues/API Errors)”">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Operation steps</p><p><strong>Step 1: Press F12 to open Developer Tools</strong></p><p><strong>Step 2: Switch to Network tab</strong></p><p><strong>Step 3: Perform the operation again</strong> (click save/refresh page)</p><p><strong>Step 4: Find the corresponding request and screenshot</strong></p><ul><li>Look at URL and status code</li><li>Look at Payload (parameters passed)</li><li>Look at Response (returned result)</li></ul><p><strong>Step 5: Send to AI</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Network information is as follows:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Request: [Screenshot 1]</span></span>
<span class="line"><span>Parameters: [Screenshot 2]</span></span>
<span class="line"><span>Response: [Screenshot 3]</span></span></code></pre></div></div><h3 id="_3-4-add-elements-information-style-issues" tabindex="-1">3.4 Add Elements Information (Style Issues) <a class="header-anchor" href="#_3-4-add-elements-information-style-issues" aria-label="Permalink to “3.4 Add Elements Information (Style Issues)”">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Operation steps</p><p><strong>Step 1: Right-click element → &quot;Inspect&quot;</strong></p><p>Developer Tools will automatically locate that element.</p><p><strong>Step 2: Screenshot the Styles panel</strong></p><p><strong>Step 3: Send to AI</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Element styles are as follows:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Screenshot]</span></span></code></pre></div></div><h2 id="_4-step-3-iterate-until-solved" tabindex="-1">4. Step 3: Iterate Until Solved <a class="header-anchor" href="#_4-step-3-iterate-until-solved" aria-label="Permalink to “4. Step 3: Iterate Until Solved”">​</a></h2><h3 id="_4-1-inefficient-approaches" tabindex="-1">4.1 Inefficient Approaches <a class="header-anchor" href="#_4-1-inefficient-approaches" aria-label="Permalink to “4.1 Inefficient Approaches”">​</a></h3><p>These approaches will waste your time:</p><ul><li>Panic when seeing an error and start randomly modifying code</li><li>Spend half an hour searching for error solutions</li><li>Try to understand the meaning of every error yourself</li><li>Debug alone until late at night</li></ul><h3 id="_4-2-efficient-approaches" tabindex="-1">4.2 Efficient Approaches <a class="header-anchor" href="#_4-2-efficient-approaches" aria-label="Permalink to “4.2 Efficient Approaches”">​</a></h3><p>Follow this process:</p><ul><li>First describe the phenomenon directly and screenshot to ask</li><li>When AI says it needs more information, open F12 to add</li><li>Modify code according to suggestions</li><li>After modifying, test; if problem persists, continue screenshotting and asking</li></ul><h2 id="_5-summary-complete-process" tabindex="-1">5. Summary: Complete Process <a class="header-anchor" href="#_5-summary-complete-process" aria-label="Permalink to “5. Summary: Complete Process”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Encounter problem</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Describe phenomenon directly + screenshot</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Send to AI: &quot;What should I do?&quot;</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>AI solves directly?</span></span>
<span class="line"><span>    ↓ Yes</span></span>
<span class="line"><span>Do what AI says</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Test if solved</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>    ↓ No / AI needs more information</span></span>
<span class="line"><span>Open F12, add key information</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Send to AI again</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Repeat until solved</span></span></code></pre></div>`,55))])}}});export{f as __pageData,y as default};
